package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.SheetSections;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Compact skills/saves/expertise workspace with retained choices and existing authoritative section saves. */
public final class ProficiencyPickerScreen extends RpgScreen {
    private final DashboardSource source;
    private JsonObject snapshot,baseline,choices;
    private CharacterCanvas pane;
    private final Set<String> touched=new HashSet<>();
    private boolean fresh;
    private Runnable resumed;
    public ProficiencyPickerScreen(Screen parent,JsonObject draft){this(parent,draft,new DashboardSource(true,text(draft,"id")));}
    public ProficiencyPickerScreen(Screen parent,JsonObject draft,DashboardSource source){super("Skills & Proficiencies",parent);this.source=source;snapshot=draft.deepCopy();baseline=snapshot.deepCopy();choices=ProficiencyModel.normalized(SheetSections.read(draft.getAsJsonObject("sheet"),"proficiencies"));}
    @Override protected int maximumWidth(){return 980;}
    @Override protected void init(){super.init();clearChildren();pane=null;busy=false;fresh=false;footer();int slot=Math.max(24,(frame.width()-108)/3),fy=frame.y()+frame.height()-30;button("Save","",frame.x()+84,fy,slot,20,this::save);button("Refresh","",frame.x()+90+slot,fy,slot,20,this::reload);button("Tools","",frame.x()+96+slot*2,fy,slot,20,()->{if(!touched.isEmpty()){message="Save these choices before editing tools and languages.";return;}if(fresh&&!busy)client.setScreen(DashboardEditors.tools(this,snapshot,source));}).hint("Tools, languages and personal entries");build();reload();}
    private void reload(){if(busy)return;request(source.read(),source.readArgs(),r->{if(r.code().equals("OK")){snapshot=SnapshotReplies.checked(source,r.data());var current=SheetSections.read(snapshot.getAsJsonObject("sheet"),"proficiencies");for(String key:List.of("skills","saves","expertise"))if(!touched.contains(key))choices.add(key,current.get(key).deepCopy());fresh=true;build();message="Proficiency adds your bonus. Expertise doubles that bonus; it does not add a second proficiency.";}else{fresh=false;message=r.message()+" Choices retained.";}});}
    private void toggle(String category,String key){if(busy)return;choices=ProficiencyModel.toggle(choices,category,key);touched.add(category);if(!category.equals("saves")){touched.add("skills");touched.add("expertise");}build();}
    private void build(){int offset=pane==null?0:pane.position();String focus=pane==null?"":pane.focusedKey();if(pane!=null)remove(pane);pane=addDrawableChild(new CharacterCanvas(new UiLayout.Rect(frame.x()+12,frame.y()+36,frame.width()-24,Math.max(24,frame.height()-74))));var view=snapshot.deepCopy();view.add("sheet",SheetSections.update(view.getAsJsonObject("sheet"),"proficiencies",ProficiencyModel.normalized(choices)));int x=6,w=pane.getWidth()-12,columns=w>=620?3:w>=320?2:1,cw=(w-(columns-1)*8)/columns,y=7;pane.label("Skills · P = proficiency, E = expertise",x,y,w,RpgTheme.GOLD);y+=19;var skills=ProficiencyModel.checks(view,false);for(int i=0;i<skills.size();i++){var c=skills.get(i);int sx=x+i%columns*(cw+8),sy=y+i/columns*23;String name=c.name();pane.control("skill:"+name,new RpgButton(sx,sy,cw-23,19,(ProficiencyModel.contains(choices,"skills",name)?"✓ ":"○ ")+name+" · "+c.ability().toUpperCase(Locale.ROOT)+" "+(ProficiencyModel.hasScores(view)?signed(c.total()):"—"),"",()->toggle("skills",name)).selected(ProficiencyModel.contains(choices,"skills",name)).hint(c.breakdown()));pane.control("expert:"+name,new RpgButton(sx+cw-20,sy,20,19,"E","",()->toggle("expertise",name)).selected(ProficiencyModel.contains(choices,"expertise",name)).accessible("Expertise in "+name).hint("Expertise doubles proficiency for this skill. Choosing it also selects proficiency."));}y+=((skills.size()+columns-1)/columns)*23+12;pane.label("Saving Throws",x,y,w,RpgTheme.GOLD);y+=19;var saves=ProficiencyModel.checks(view,true);for(int i=0;i<saves.size();i++){var c=saves.get(i);int sx=x+i%columns*(cw+8),sy=y+i/columns*23;pane.control("save:"+c.ability(),new RpgButton(sx,sy,cw,19,(ProficiencyModel.contains(choices,"saves",c.ability())?"✓ ":"○ ")+c.name()+" "+(ProficiencyModel.hasScores(view)?signed(c.total()):"—"),"",()->toggle("saves",c.ability())).selected(ProficiencyModel.contains(choices,"saves",c.ability())).hint(c.breakdown()));}y+=((saves.size()+columns-1)/columns)*23+9;var identity=SheetSections.read(snapshot.getAsJsonObject("sheet"),"identity");String clazz=text(identity,"characterClass");pane.wrapped((Srd2014Catalog.classSkills(clazz).isEmpty()?"Discuss class skill choices with your DM.":clazz+": choose "+Srd2014Catalog.classSkillCount(clazz)+" class skills; additional choices need DM review.")+" Existing background choices are kept. These tabletop choices do not change automated combat.",x,y,w,RpgTheme.MUTED);pane.position(offset);if(!focus.isEmpty()){pane.focus(focus);setInitialFocus(pane);}}
    private void save(){if(!fresh||busy)return;if(needsEditReview(baseline,snapshot)){long expected=revision(snapshot);client.setScreen(new RpgConfirmationScreen(this,"Review changed proficiencies?","Your character changed while these choices were open. Keep your choices after reviewing the saved character?",()->{if(revision(snapshot)==expected){baseline=snapshot.deepCopy();resumed=this::save;}}));return;}var data=SheetSections.read(snapshot.getAsJsonObject("sheet"),"proficiencies");for(String key:touched)data.add(key,choices.get(key).deepCopy());data=ProficiencyModel.normalized(data);request(source.edit(),source.sectionArgs(snapshot,"proficiencies",data),r->{if(r.code().equals("OK")){snapshot=SnapshotReplies.checked(source,r.data());touched.clear();client.setScreen(parent);}else{fresh=false;message=r.message()+" Choices retained. Refresh and review before retrying.";}});}
    @Override public void tick(){super.tick();if(resumed!=null&&!busy&&fresh){var next=resumed;resumed=null;next.run();}}
    @Override public void close(){if(busy)return;if(!touched.isEmpty())client.setScreen(new RpgConfirmationScreen(this,"Discard unsaved choices?","Saved proficiencies remain unchanged.",()->client.setScreen(parent)));else super.close();}
    private static String signed(int value){return (value>=0?"+":"")+value;}
}
